<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Brickfall</title>
<style>
:root{color-scheme:dark;--bg:#0d1020;--panel:#151a30;--line:#2b335a;--txt:#eef3ff;--mut:#9aa7d6;--acc:#67e8f9;--warn:#f59e0b;--bad:#fb7185;--good:#34d399}
