function parseWorkbook() { const wb = XLSX.readFile(ASSET_XLSX); const rows = n => XLSX.utils.sheet_to_json(wb.Sheets[n], { defval: null }); return { users: rows('Users'), levels: rows('Levels'), bricks: rows('Bricks'), leaderboard: rows('Leaderboard'), constants: rows('Constants') }; }
