content:
const $=s=>document.querySelector(s), state={token:localStorage.getItem('brickfall_token')||'', user:null, leaderboard:[], levels:[], bricks:[], constants:[], run:null, view:'game', assist:false, keys:{}, pointer:false, msg:[], lastSave:0, lab:null};
const api=async(path,opts={})=>{const h=opts.headers||{}; h['Content-Type']='application/json'; if(state.token) h.Authorization='Bearer '+state.token; const r=await fetch(path,{...opts,headers:h}); if(r.status===401){state.token=''; localStorage.removeItem('brickfall_token'); renderAuth(); throw new Error('unauthorized');} return r;};
function op(){return crypto.randomUUID()} function setMsg(t){$('#message').textContent=t; state.msg.unshift(t); state.msg=state.msg.slice(0,5); $('#recent').innerHTML=state.msg.map(x=>`<div>${x}</div>`).join('');}
function renderAuth(){const on=!!state.token; $('#authCard').classList.toggle('hidden',on); $('#playerCard').classList.toggle('hidden',!on);}
function renderHud(){const u=state.user||{}; $('#playerName').textContent=u.name||'Signed out'; $('#playerMeta').textContent=u.email?`${u.email} · ${u.initials}`:''; $('#score').textContent=state.run?.score??0; $('#lives').textContent=state.run?.lives??3; $('#level').textContent=state.run?.level??1; $('#combo').textContent='x'+(state.run?.combo??1); $('#power').textContent=state.run?.power?.type||'none'; $('#timer').textContent=state.run?.power?Math.ceil(state.run.power.remaining||0):0; $('#rev').textContent=u.revision??1; $('#best').textContent=u.bestScore??0; $('#syncText').textContent=state.run?`sync r${u.revision}`:'sync idle'; $('#statusText').textContent=state.run?state.run.status:'menu'; $('#assistBtn').setAttribute('aria-pressed',String(state.assist)); $('#assistBtn').textContent='Assist paddle: '+(state.assist?'on':'off'); const sel=$('#levelSelect'); sel.innerHTML=''; for(let i=1;i<=Math.max(10,u.highestLevel||1);i++){const o=document.createElement('option');o.value=i;o.textContent=`Level ${i}${i<=u.highestLevel?'':' (locked)'}`; if(i>u.highestLevel)o.disabled=true; sel.appendChild(o)}}
function renderLeaderboard(){ $('#leaderboard').innerHTML=state.leaderboard.map((r,i)=>`<div class=card>#${i+1} ${r.initials} — ${r.score} · L${r.level}</div>`).join(''); }
function draw(){const c=$('#game'), g=c.getContext('2d'); g.clearRect(0,0,c.width,c.height); g.fillStyle='#0b1020'; g.fillRect(0,0,c.width,c.height); if(!state.run){g.fillStyle='#fff'; g.fillText('Sign in to start',40,40); return;} const r=state.run; g.fillStyle='#203059'; g.fillRect(r.paddle.x-r.paddle.w/2,560,r.paddle.w,16); g.fillStyle='#fff'; r.balls.forEach(b=>{g.beginPath();g.arc(b.x,b.y,7,0,Math.PI*2);g.fill()}); r.bricks.forEach(br=>{if(br.state==='gone')return; g.fillStyle=br.type==='solid'?'#4b5563':br.type==='strong'&&(br.hp<2)?'#f59e0b':'#67e8f9'; g.fillRect(br.x,br.y,br.w,br.h); g.strokeStyle='#000'; g.strokeRect(br.x,br.y,br.w,br.h)});
requestAnimationFrame(draw)}
async function load(){if(!state.token){renderAuth(); renderHud(); draw(); return;} try{const d=await api('/api/bootstrap').then(r=>r.json()); state.user=d.user; state.leaderboard=d.leaderboard; state.levels=d.levels; state.bricks=d.bricks; state.constants=d.constants; renderAuth(); renderLeaderboard(); renderHud(); populateLab(); if(state.user.run) state.run=state.user.run; setMsg('Signed in as '+state.user.name);}catch{renderAuth()}}
function populateLab(){const s=$('#drillSelect'); s.innerHTML=''; ['Brick types','Power relay','Multiball','Sticky catch','Extra life','Last ball','Final wall'].forEach((n,i)=>{const o=document.createElement('option');o.value=i;o.textContent=n;s.appendChild(o)}); if(state.lab) $('#drillView').textContent=JSON.stringify(state.lab,null,2)}
async function signIn(){const email=$('#email').value,password=$('#password').value; const d=await api('/api/auth/signin',{method:'POST',body:JSON.stringify({email,password})}).then(r=>r.json()); state.token=d.token; localStorage.setItem('brickfall_token',state.token); state.user=d.user; state.leaderboard=d.leaderboard; renderAuth(); renderLeaderboard(); renderHud(); setMsg('Signed in ' + d.user.email); }
async function signOut(){if(!state.token)return; await api('/api/auth/signout',{method:'POST',body:'{}'}).catch(()=>{}); state.token=''; localStorage.removeItem('brickfall_token'); state.user=null; state.run=null; renderAuth(); renderHud(); setMsg('Signed out');}
$('#signInBtn').onclick=signIn; $('#signOutBtn').onclick=signOut; $('#assistBtn').onclick=()=>{state.assist=!state.assist; renderHud(); setMsg('Assist '+(state.assist?'enabled':'disabled'));};
$('#launchBtn').onclick=()=>setMsg('Launch requested'); $('#pauseBtn').onclick=()=>setMsg('Pause toggled'); $('#restartBtn').onclick=()=>setMsg('Restart requested');
$('#tabGame').onclick=()=>{$('#labPanel').classList.add('hidden'); $('#tabLab').classList.remove('primary'); $('#tabGame').classList.add('primary');}; $('#tabLab').onclick=()=>{$('#labPanel').classList.remove('hidden'); $('#tabLab').classList.add('primary'); $('#tabGame').classList.remove('primary');};
$('#advanceBtn').onclick=async()=>{const d={drill:$('#drillSelect').value}; state.lab={drill:d.drill,phase:'paused',telemetry:'stub'}; $('#drillView').textContent=JSON.stringify(state.lab,null,2)};
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)) state.assist=false;}); load(); draw();

